args.sparql:
SELECT ?film ?director ?directorLabel ?deathDate WHERE {
  VALUES ?film { dbr:Le_foto_proibite_di_una_signora_per_bene dbr:Licenza_premio }
  {
    ?film dbo:director ?director .
  } UNION {
    ?film dbp:director ?director .
  }
  OPTIONAL { ?director dbo:deathDate ?deathDate . }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = "en") }
}

SELECT ?film ?director ?deathDate WHERE {
  VALUES ?film { dbr:Le_foto_proibite_di_una_signora_per_bene dbr:Licenza_premio }
  ?film (dbo:director|dbp:director) ?director .
  OPTIONAL { ?director dbo:deathDate ?deathDate }
}
ORDER BY DESC(?deathDate)
LIMIT 1

